add_action( 'woocommerce_after_variations_form', 'perfectpixel_image_background_by_color' );

function perfectpixel_image_background_by_color() {
	$map = array();
	foreach ( explode( '|', '{{bg_color_map}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && preg_match( '/^(#[0-9a-f]{3,8}|[a-z]+)$/i', $parts[1] ) ) {
			$map[ sanitize_title( $parts[0] ) ] = $parts[1];
		}
	}
	$cfg = array(
		'field' => 'attribute_' . sanitize_title( '{{bg_color_attribute}}' ),
		'map'   => $map,
	);
	?>
	<script>
	jQuery( function ( $ ) {
		var cfg   = <?php echo wp_json_encode( $cfg ); ?>;
		var image = $( '.woocommerce-product-gallery__image' ).first();
		var apply = function () {
			var slug  = $( 'form.variations_form [name="' + cfg.field + '"]' ).val() || '';
			var color = cfg.map[ slug ] || ( /^[a-z]+$/i.test( slug ) ? slug : '' );
			image.css( { backgroundColor: color, transition: 'background-color .3s' } );
		};
		$( 'form.variations_form' ).on( 'change', '[name="' + cfg.field + '"]', apply ).on( 'reset_data', apply );
		apply();
	} );
	</script>
	<?php
}
